def valid_date(date):
    if len(date) != 10:
        return False
    parts = date.split('-')
    if len(parts) != 3:
        return False
    for part in parts:
        if not part.isdigit():
            return False
    month_str, day_str, year_str = parts
    month = int(month_str)
    day = int(day_str)
    year = int(year_str)
    if month < 1 or month > 12:
        return False
    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif month in [4, 6, 9, 11]:
        max_days = 30
    elif month == 2:
        is_leap = False
        if year % 4 == 0:
            if year % 100 == 0:
                if year % 400 == 0:
                    is_leap = True
            else:
                is_leap = True
        max_days = 29 if is_leap else 28
    else:
        return False
    if day < 1 or day > max_days:
        return False
    return True
```

